<?php declare(strict_types=1); namespace App\Controller; use Cake\Http\Response; class PagosParqueaderosController extends AppController { public function index():?Response {$this->set('items',$this->PagosParqueaderos->find()->contain(['AsignacionesParqueaderos.Parqueaderos','AsignacionesParqueaderos.Copropietarios'])->all());return null;} public function add():?Response {$item=$this->PagosParqueaderos->newEmptyEntity();if($this->request->is('post')){$item=$this->PagosParqueaderos->patchEntity($item,$this->request->getData());if($this->PagosParqueaderos->save($item))return $this->redirect(['action'=>'index']);}$this->set(compact('item'));$this->set('asignaciones',$this->fetchTable('AsignacionesParqueaderos')->find('list')->all());return null;} public function edit(int $id):?Response {$item=$this->PagosParqueaderos->get($id);if($this->request->is(['post','put','patch'])){$item=$this->PagosParqueaderos->patchEntity($item,$this->request->getData());if($this->PagosParqueaderos->save($item))return $this->redirect(['action'=>'index']);}$this->set(compact('item'));$this->set('asignaciones',$this->fetchTable('AsignacionesParqueaderos')->find('list')->all());return null;} }
